return [{ json: { url: m[0].replace(/&amp;/g, '&') } }];

const item = $input.first();
item.binary.data.fileName = 'pricefull.xml.gz';
item.binary.data.fileExtension = 'gz';
item.binary.data.mimeType = 'application/gzip';
return [item];

// קורא את קובץ ה-PriceFull, מסנן מוצרים במשקל, ומחלק למנות של 1,000
// חוץ מהמוצרים במשקל שבסל (WEIGHTED): הם נשמרים, עם מחיר לק"ג ב-price_per_kg
const WEIGHTED = new Set([
  '7290000964775', // בננות
  '7290000000480', // בצל יבש
  '7290000000138', // כרוב לבן
  '7290000000046', // מלפפונים
  '7290000000022', // עגבניות
  '7290000000091', // פלפל אדום
  '7290000000596', // תפוחי אדמה
  '7290009137507', // תפוחי עץ גרני סמית
  '7290000933740', // בשר בקר טחון
  '7290009011043', // פילה אמנון
  '7290000616827', // חזה עוף
  '7290001303436', // עוף שלם טרי
]);
const xml = $input.first().json.data;
const loadedAt = new Date().toISOString();
const seen = new Set();
const rows = [];
const re = /<Item>([\s\S]*?)<\/Item>/g;
let m;
while ((m = re.exec(xml))) {
  const s = m[1];
  const g = (t) => {
    const r = s.match(new RegExp('<' + t + '>([\\s\\S]*?)</' + t + '>', 'i'));
    return r ? r[1].trim() : '';
  };
  const code = g('ItemCode');
  const price = parseFloat(g('ItemPrice'));
  const weighted = (g('bIsWeighted') || g('blsWeighted')) === '1';
  const kg = WEIGHTED.has(code);
  if (!code || (weighted && !kg) || !(price > 0) || seen.has(code)) continue;
  // מוצר במשקל: המחיר בקובץ הוא לק"ג. אריזה במשקל משוער (וולט): המחיר חלקי משקל האריזה
  let perKg = null;
  if (kg) {
    const q = parseFloat(g('Quantity'));
    const unitQty = g('UnitQty');
    const kgInPack = /קילו|ק"ג/.test(unitQty) ? q : /גרם/.test(unitQty) ? q / 1000 : null;
    perKg = weighted ? price : kgInPack > 0 ? Math.round((price / kgInPack) * 100) / 100 : null;
  }
  seen.add(code);
  const updated = g('PriceUpdateTime').replace(' ', 'T');
  rows.push({
    chain_id: 'shufersal',
    item_code: code,
    item_name: g('ItemName').replace(/\s+/g, ' '),
    manufacturer: g('ManufactureName') || null,
    quantity: parseFloat(g('Quantity')) || null,
    unit: g('UnitOfMeasure') || g('UnitQty') || null,
    price,
    price_per_kg: perKg,
    price_updated_at: updated || null,
    loaded_at: loadedAt,
  });
}
if (rows.length < 1000) throw new Error('נמצאו רק ' + rows.length + ' מוצרים בקובץ. לא כותבים כלום.');
// קוד של מוצר במשקל שלא נמצא בקובץ: המוצר יופיע כחסר ברשת. הרשימה נשמרת ביומן ההרצה
const missingWeighted = [...WEIGHTED].filter((c) => !seen.has(c));
if (missingWeighted.length) console.log('שופרסל: מוצרים במשקל שלא נמצאו:', missingWeighted.join(', '));
const batches = [];
for (let i = 0; i < rows.length; i += 1000) batches.push({ json: { rows: rows.slice(i, i + 1000) } });
if (batches.length) batches[0].json.missing_weighted = missingWeighted;
return batches;

