}
for (const m of matches) if (!catalog.has(m.item_code)) catalog.set(m.item_code, { barcode: m.barcode, kg: false });
const codes = [...products.filter((p) => p.unit !== 'kg').map((p) => p.barcode), ...matches.map((m) => m.item_code)];
