// שמות הקבצים ב-Cerberus לפעמים באותיות קטנות, ולכן בלי תלות ברישיות
const list = ($input.first().json.aaData || []).map((f) => f.fname).filter((n) => /^promofull7290639000004-\d{3}-002-/i.test(n)).sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
